create table flow (step_count integer not null, amount bigint, started_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, failed_step varchar(255), flow_id varchar(255) not null, flow_key varchar(255) not null, flow_type varchar(255) not null, last_step varchar(255) not null, membership_id varchar(255), status varchar(255) not null check ((status in ('IN_PROGRESS','SUCCEEDED','FAILED'))), primary key (flow_key));
create table flow_step (amount bigint, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, reason varchar(500), flow_id varchar(255) not null, flow_type varchar(255) not null, membership_id varchar(255), outcome varchar(255) not null check ((outcome in ('IN_PROGRESS','SUCCEEDED','FAILED'))), service varchar(255) not null, step varchar(255) not null, primary key (id), constraint flow_step_once unique (flow_type, flow_id, step));
create index flow_by_start on flow (started_at);
create index flow_by_update on flow (updated_at);
create index flow_step_of_flow on flow_step (flow_type, flow_id);
